            // [83] BB\script\output\_sce04_c402_0050_eng#2
            entryTranslators[@"BB\script\output\_sce04_c402_0050_eng#2"] = (s) => {
                R(ref s, "Order!<E003 4> Order!<E003 6> <E025 1>Order in court!", "Silence !<E003 4> Silence !<E003 6> <E025 1>Silence dans le prétoire !");
                R(ref s, "Lord van Zieks...", "Lord Van Peers...");
