                R(ref s, "Tell me...<E049><E003 16><E025 2><E330>did your brother own a dog?", "Dites-moi...<E049><E003 16><E025 2><E330>votre frère possédait-il un chien ?");
                R(ref s, "Yes.<E049><E003 12> He did.", "Oui.<E049><E003 12> En effet.");
                R(ref s, "Balmung.<E049><E003 14> He was a well known hunting dog.<E049><E003 12>\r\nPeople called him a giant.", "Balmung.<E049><E003 14> C'était un chien de chasse renommé.<E049><E003 12>\r\nOn le qualifiait de géant.");
