                R(ref s, "After Klint's death, <E049><E003 8>the creature passed away too...<E049><E003 14>\r\n<E025 3>almost as if he were following his master.", "Après la mort de Klint, <E049><E003 8>la bête a péri elle aussi...<E049><E003 14>\r\n<E025 3>comme si elle suivait son maître dans l'au-delà.");
                R(ref s, "He was a magnificent hunting dog...<E049><E003 16><E239>worthy of the\r\njewel-studded collar around his neck.", "C'était un magnifique chien de chasse...<E049><E003 16><E239>digne du\r\ncollier orné de pierreries qu'il portait au cou.");
                R(ref s, "A jewel-studded collar...?", "Un collier orné de pierreries... ?");
