                R(ref s, "...some years ago now <E049><E003 10>it was stolen by a thief who broke\r\ninto the house one night.", "...il y a quelques années de cela, <E049><E003 10>il fut dérobé par un cambrioleur\r\nqui s'était introduit chez nous en pleine nuit.");
                R(ref s, "(A jewel-studded collar, <E003 8>stolen by a thief...)", "(Un collier serti de pierreries, <E003 8>volé par un cambrioleur...)");
                R(ref s, "It so happens, <E049><E003 10><E333>that myself and my colleagues have come\r\nacross such a collar during our time in London.", "Il se trouve <E049><E003 10><E333>que mes amis et moi-même avons croisé la route\r\nd'un tel collier lors de notre séjour à Londres.");
                R(ref s, "...How could you...?", "...Comment auriez-vous pu... ?");
                R(ref s, "There was <E171 1 16 0 10 2>an old <E006>emblem<E005> attached to the collar, too,<E049><E003 8>\r\nmade of pure gold.", "Il y avait <E171 1 16 0 10 2>un vieil <E006>emblème<E005> fixé à ce collier,<E049><E003 8>\r\nforgé dans de l'or pur.");
                R(ref s, "It was topped with a small crown <E003 8><E025 3>and bore an ornate\r\ncapital letter ‘B’...", "Il était surmonté d'une petite couronne <E003 8><E025 3>et frappé d'une lettre\r\nmajuscule ouvragée, un « B »...");
                R(ref s, "What?!<E049><E003 20>\r\n<E025 3><E341>An emblem bearing the initial ‘B’?", "Quoi ?!<E049><E003 20>\r\n<E025 3><E341>Un emblème frappé de l'initiale « B » ?");
                R(ref s, "Oh my!<E049><E003 12> <E145 9 92><E117 9 8><E003 5><E346><E025 1>You know it?!", "Ciel !<E049><E003 12> <E145 9 92><E117 9 8><E003 5><E346><E025 1>Vous le reconnaissez ?!");
                R(ref s, "...It's the insignia <E049><E003 7><E145 18 0><E118 18 1.20><E003 30><E239><E025 3>of the <E006>Baskerville<E005> family.", "...C'est le blason <E049><E003 7><E145 18 0><E118 18 1.20><E003 30><E239><E025 3>de la famille <E006>Baskerville<E005>.");
                R(ref s, "WHAT?!<E049><E003 14> <E025 2>The Baskerville...<E049><E003 15>\r\n<E341><E025 2><E007>(Why is THAT name coming up now...?)", "QUOI ?!<E049><E003 14> <E025 2>Les Baskerville...<E049><E003 15>\r\n<E341><E025 2><E007>(Pourquoi CE nom ressurgit-il maintenant... ?)");
                R(ref s, "Baskerville <E049><E003 8><E025 3>is the family name of my late brother's\r\nwidow.", "Baskerville <E049><E003 8><E025 3>est le patronyme de la veuve de mon\r\nregretté frère.");
                R(ref s, "That pure gold emblem was an heirloom, <E049><E003 8>which Klint\r\nacquired upon their marriage.", "Cet emblème en or pur était un héritage familial, <E049><E003 8>que Klint\r\navait reçu lors de leurs épousailles.");
                R(ref s, "There can be no doubt then.<E049><E003 20>\r\n<E025 3><E239>The collar you've described was Balmung's.", "Il n'y a plus aucun doute possible.<E049><E003 20>\r\n<E025 3><E239>Le collier dont vous parlez était celui de Balmung.");
