                R(ref s, "So is it true then...?", "C'est donc vrai... ?");
                R(ref s, "Klint van Zieks <E003 8><E025 2><E335><E342>really was the Professor...", "Klint Van Peers <E003 8><E025 2><E335><E342>était bel et bien le Professeur...");
                R(ref s, "Impossible!<E003 16> <E345><E342><E025 1>These Japanese are\r\n<E042><CNTR>making it all up to exonerate their own!", "Impossible !<E003 16> <E345><E342><E025 1>Ces Japonais inventent\r\n<E042><CNTR>tout cela de toutes pièces pour disculper l'un des leurs !");
                R(ref s, "So in fact, <E049><E003 8>the person responsible for these murders of\r\nnobles and royals was a noble himself.", "Ainsi donc, <E049><E003 8>le coupable de ces meurtres d'aristocrates et\r\nde membres de la famille royale était lui-même un noble.");
                R(ref s, "And that threatened to be an enormous scandal that would\r\nirrevocably destabilise British society.", "Et cela risquait de provoquer un scandale sans précédent qui\r\nébranlerait irréversiblement la société britannique.");
                R(ref s, "My father knew that, <E049><E003 8><E025 2>and was using it to negotiate his\r\nway out of the unjust charges brought against him.", "Mon père le savait, <E049><E003 8><E025 2>et s'en servait comme monnaie d'échange face\r\naux accusations mensongères portées contre lui.");
                R(ref s, "But at the very last hour, <E049><E003 14><E145 112 0><E118 112 0.5><E025 2>those he'd bargained with\r\nbetrayed him...<E003 12><E025 3>slaying him mercilessly on foreign soil.", "Mais au tout dernier moment, <E049><E003 14><E145 112 0><E118 112 0.5><E025 2>ceux avec qui il avait négocié\r\nl'ont trahi... <E003 12><E025 3>l'abattant sans merci sur une terre étrangère.");
                R(ref s, "Well?<E049><E003 20> <E164 1 8 1 2 8 0 2 0><E139 1><E339>Can you deny it...<E003 14>Lord Stronghart?!", "Alors ?<E049><E003 20> <E164 1 8 1 2 8 0 2 0><E139 1><E339>Pouvez-vous le nier...<E003 14>Lord Stronghart ?!");
