                R(ref s, "And still now, <E049><E003 8>the six million inhabitants of our great\r\ncapital rest easy believing that justice was done.", "Et aujourd'hui encore, <E049><E003 8>les six millions d'âmes de notre fière\r\ncapitale dorment en paix, persuadées que justice fut rendue.");
                R(ref s, "That though his anonymity remains, <E049><E003 10><E145 61 2><E003 5><E025 3>the diabolical\r\nmurderer was caught and executed.", "Que malgré l'anonymat préservé du monstre, <E049><E003 10><E145 61 2><E003 5><E025 3>ce meurtrier\r\ndiabolique a été châtié et conduit à l'échafaud.");
                R(ref s, "Very well then.<E049><E003 20>\r\n<E239><E025 3>...You may have the truth.", "Soit.<E049><E003 20>\r\n<E239><E025 3>...Vous aurez la vérité.");
                R(ref s, "Tell me then!<E049><E003 15>\r\n<E025 2><E341>Tell me what Klint really was!", "Dites-le-moi, alors !<E049><E003 15>\r\n<E025 2><E341>Dites-moi qui était réellement Klint !");
