            // [84] BB\script\output\_sce04_c402_0060_eng#2
            entryTranslators[@"BB\script\output\_sce04_c402_0060_eng#2"] = (s) => {
                R(ref s, "The 19th century was a truly miraculous hundred\r\n<E042><CNTR>years for Great Britain...<E003 12><E025 3>and indeed the whole world.", "Le XIXe siècle fut un siècle véritablement prodigieux\r\n<E042><CNTR>pour la Grande-Bretagne...<E003 12><E025 3>et pour le monde entier.");
                R(ref s, "New industry, <E003 6>new technology, <E003 8>and with the birth of\r\n<E042><CNTR>the Metropolitan Police Service, <E003 10><E025 3>new law and order.", "Industrie nouvelle, <E003 6>technologies inédites, <E003 8>et avec la création\r\n<E042><CNTR>de la police métropolitaine, <E003 10><E025 3>un ordre public nouveau.");
                R(ref s, "But these dazzling new developments meant\r\n<E042><CNTR>ever deeper shadows were cast on society.", "Mais ces progrès fulgurants projetaient\r\n<E042><CNTR>des ombres de plus en plus ténébreuses sur la société.");
                R(ref s, "Water sullied by factories, <E003 8>air thick with noxious\r\n<E042><CNTR>fumes <E003 8>and crime...<E003 12>growing daily to fill the darkness.", "Des eaux polluées par les usines, <E003 8>un air empesté de vapeurs\r\n<E042><CNTR>toxiques, <E003 8>et le crime...<E003 12>proliférant chaque jour dans l'obscurité.");
                R(ref s, "Lord Klint van Zieks made it his\r\n<E042><CNTR>mission to combat that darkness.", "Lord Klint Van Peers s'était donné pour\r\n<E042><CNTR>mission d'affronter ces ténèbres.");
                R(ref s, "But as time went on, <E049><E003 15><E074 1 8><E025 3>it slowly ate at his soul, <E003 10>\r\n<E042><CNTR>until eventually...<E003 12><E025 3>he was consumed.", "Mais au fil du temps, <E049><E003 15><E074 1 8><E025 3>elles ont lentement rongé son âme, <E003 10>\r\n<E042><CNTR>jusqu'à ce que, finalement...<E003 12><E025 3>il en soit totalement consumé.");
                R(ref s, "It's ironic, <E049><E003 10><E025 3>really –<E049><E003 10> and somewhat surprising –<E049><E003 10> that the\r\ntruth has once again been unearthed...", "C'est une cruelle ironie, <E049><E003 10><E025 3>en vérité –<E049><E003 10> et une surprise singulière –<E049><E003 10> de voir la\r\nvérité à nouveau déterrée...");
                R(ref s, "...by a Japanese.", "...par un Japonais.");
                R(ref s, "Once again?<E049><E003 12>\r\n<E025 1><E164 112 7 1 2 1 0 1 1><E149 112 0 4><E139 112>What do you mean?!", "À nouveau ?<E049><E003 12>\r\n<E025 1><E164 112 7 1 2 1 0 1 1><E149 112 0 4><E139 112>Que voulez-vous dire ?!");
                R(ref s, "Ten years ago, <E049><E003 12><E145 61 7><E118 61 0.7><E025 3>your father, <E003 4>Genshin Asogi, <E049><E003 8>turned up at\r\nmy office one night...", "Il y a dix ans, <E049><E003 12><E145 61 7><E118 61 0.7><E025 3>votre père, <E003 4>Genshin Asogi, <E049><E003 8>s'est présenté dans\r\nmon bureau un soir...");
                R(ref s, "The Professor?!", "Le Professeur ?!");
                R(ref s, "Yes, <E003 10>beyond all shadow of doubt.<E003 12>\r\n<E025 1><E341>You must issue a warrant to search his home at once!", "Oui, <E003 10>sans l'ombre d'un doute.<E003 12>\r\n<E025 1><E341>Vous devez délivrer un mandat de perquisition sur-le-champ !");
                R(ref s, "...Don't be absurd.", "...Ne soyez pas ridicule.");
                R(ref s, "The man comes from one of our country's most illustrious\r\nfamilies.<E003 10> <E025 2>He's a paragon of justice here in the capital.", "Cet homme est issu de l'une des familles les plus prestigieuses de ce\r\nroyaume.<E003 10> <E025 2>C'est un parangon de justice dans toute la capitale.");
                R(ref s, "Yes, <E003 10><E025 1>that's the point!<E003 13> <E025 1>That's why none of you British can\r\nsee it!", "Oui, <E003 10><E025 1>c'est précisément là le problème !<E003 13> <E025 1>Voilà pourquoi aucun\r\nBritannique ne parvient à le voir !");
                R(ref s, "He's using his noble status as a diversion <E003 10><E025 1><E346>whilst he\r\ncommits these atrocious crimes behind the scenes!", "Il use de son rang noble comme d'un paravent <E003 10><E025 1><E346>pendant qu'il\r\nperpétue ces crimes indicibles dans l'ombre !");
                R(ref s, "...Do you have evidence?", "...Avez-vous des preuves ?");
                R(ref s, "Nothing definitive <E003 8>as yet.", "Rien de décisif <E003 8>pour le moment.");
                R(ref s, "But he keeps an enormous, <E003 6>savage hound on the estate.", "Mais il abrite un molosse féroce d'une taille colossale sur sa propriété.");
                R(ref s, "We need the full support of the judiciary for this!<E003 12>\r\n<E346><E343><E025 1>We're up against a member of the aristocracy!", "Nous avons besoin du soutien indéfectible de la justice pour cela !<E003 12>\r\n<E346><E343><E025 1>Nous nous attaquons à un membre de l'aristocratie !");
                R(ref s, "...So a large family estate has a fierce guard dog.<E003 12>\r\n<E025 3>You should know that's commonplace here in Britain.", "...Qu'un vaste domaine familial possède un chien de garde féroce...<E003 12>\r\n<E025 3>C'est chose tout à fait courante en Grande-Bretagne.");
                R(ref s, "I'm sorry, <E003 12><E025 2>but I can't possibly put Scotland Yard onto this\r\nbased on the tenuous accusation of a visiting student.", "Je suis navré, <E003 12><E025 2>mais je ne puis lancer Scotland Yard sur de simples\r\nsoupçons émanant d'un étudiant étranger.");
