                R(ref s, "(...by taking the drastic measure <E049><E003 8><E025 2><E341><E338>of <E006>ending the\r\nperpetrator's life<E007>!)", "(...en recourant à la mesure suprême <E049><E003 8><E025 2><E341><E338><E006>d'ôter la vie\r\nau criminel<E007> !)");
                R(ref s, "As soon as I heard, <E049><E003 8>I hurried to the mansion.<E049><E003 10> <E025 3>When I\r\narrived, <E049><E003 8>it was easy to grasp what had happened.", "Dès que je l'ai appris, <E049><E003 8>je me suis précipité au manoir.<E049><E003 10> <E025 3>À mon\r\narrivée, <E049><E003 8>il ne fut guère malaisé de comprendre la situation.");
                R(ref s, "And?<E049><E003 10> <E164 112 7 1 2 1 0 1 1><E139 112><E025 2>What about the will?", "Et alors ?<E049><E003 10> <E164 112 7 1 2 1 0 1 1><E139 112><E025 2>Qu'en est-il du testament ?");
                R(ref s, "Asogi must have already taken it.<E049><E003 12>\r\nNothing of that nature was found at the scene.", "Asogi avait déjà dû s'en emparer.<E049><E003 12>\r\nAucun document de ce genre n'a été découvert sur les lieux.");
