            // [86] BB\script\output\_sce04_c402_0060_eng#4
            entryTranslators[@"BB\script\output\_sce04_c402_0060_eng#4"] = (s) => {
                R(ref s, "I was the only person who knew of the true identity of\r\nthe Professor.", "J'étais la seule personne au monde à connaître la véritable identité\r\ndu Professeur.");
                R(ref s, "So...<E003 15><E145 61 4><E118 61 0.5><E025 3>I resolved to keep it a secret <E049><E003 8>and to guard the secret\r\nto the bitter end.", "Dès lors... <E003 15><E145 61 4><E118 61 0.5><E025 3>j'ai résolu d'en garder le secret <E049><E003 8>et de l'emporter\r\ndans ma tombe.");
                R(ref s, "S-<E049><E003 8><E341>So you're admitting to it?<E049><E003 20>\r\nThat...<E003 10><E342><E338><E025 2>you were behind it all?!", "A-<E049><E003 8><E341>Alors vous reconnaissez les faits ?<E049><E003 20>\r\nQue... <E003 10><E342><E338><E025 2>vous étiez derrière toute cette machination ?!");
                R(ref s, "It was you, then, <E049><E003 10><E164 112 7 1 2 5 0 2 1><E139 112><E025 1>who pinned the crimes on my father!", "C'est donc vous <E049><E003 10><E164 112 7 1 2 5 0 2 1><E139 112><E025 1>qui avez fait porter le chapeau à mon père !");
                R(ref s, "...I did what needed to be done in order to protect the law\r\nand order of the British Empire.", "...J'ai fait ce qui s'imposait pour protéger l'ordre et la paix\r\nde l'Empire britannique.");
                R(ref s, "Even if that meant employing an unforgivable ruse.", "Dût-il m'en coûter de recourir à un stratagème inexcusable.");
                R(ref s, "Then it was you who arranged this fabricated evidence!", "C'est donc vous qui avez fabriqué ces fausses preuves !");
                R(ref s, "I ordered that detective to take care of it.<E049><E003 13><E145 61 10><E118 61 1.2><E003 15>\r\n<E025 3>Whilst keeping the truth from him, <E049><E003 8>naturally.", "J'ai ordonné à cet inspecteur de s'en charger.<E049><E003 13><E145 61 10><E118 61 1.2><E003 15>\r\n<E025 3>Tout en lui dissimulant la vérité, <E049><E003 8>naturellement.");
                R(ref s, "Gregson...?", "Gregson... ?");
                R(ref s, "Obviously, <E049><E003 10>he opposed me at first.", "De toute évidence, <E049><E003 10>il s'y est opposé au début.");
                R(ref s, "Are you off your rocker?!<E049><E003 20>\r\n<E025 1><E346><E342>We can't do somethin' like that!", "Vous avez perdu la tête ou quoi ?!<E049><E003 20>\r\n<E025 1><E346><E342>On ne peut pas faire une chose pareille !");
                R(ref s, "There's no question <E049><E003 10>that it was Asogi who murdered\r\nLord van Zieks.", "Il ne fait aucun doute <E049><E003 10>qu'Asogi a assassiné\r\nLord Van Peers.");
                R(ref s, "The house staff have made statements <E145 7 65><E118 7 0.8>that they saw the\r\nman running from the mansion that night.", "Les domestiques ont déclaré <E145 7 65><E118 7 0.8>avoir vu cet homme\r\ns'enfuir du domaine en courant cette nuit-là.");
                R(ref s, "Yes, <E049><E003 8>well...<E049><E003 14><E025 2>I've no doubt it was that Japanese fella.", "Oui, <E049><E003 8>enfin... <E049><E003 14><E025 2>je n'doute point qu'ce soit c'gaillard d'Japonais.");
                R(ref s, "But we haven't got a shred of conclusive evidence against\r\nthe man!", "Mais on n'a pas la moindre bribe de preuve irréfutable contre\r\nlui !");
                R(ref s, "And worse than that, <E049><E003 10><E145 7 65>he doesn't keep a dog.<E049><E003 14>\r\n<E025 2>So we're short of a murder weapon to boot!", "Et y a pire que tout : <E049><E003 10><E145 7 65>il n'possède pas l'moindre chien.<E049><E003 14>\r\n<E025 2>On n'a donc même pas d'arme du crime à présenter !");
                R(ref s, "And we're short on time, <E049><E003 6><E025 3>Gregson!", "Et le temps nous est compté, <E049><E003 6><E025 3>Gregson !");
                R(ref s, "We must put a stop to this man's rampage!<E049><E003 15>\r\n<E025 1>For the good of the country!", "Nous devons stopper ce massacre au plus vite !<E049><E003 15>\r\n<E025 1>Pour le salut de la nation !");
                R(ref s, "So we'll <E171 14 1 1 6 2>use whatever means necessary.<E049><E003 15>\r\n<E025 3>...Do I make myself clear, <E049><E003 8>detective?", "Nous emploierons donc <E171 14 1 1 6 2>tous les moyens nécessaires.<E049><E003 15>\r\n<E025 3>...Me suis-je bien fait comprendre, <E049><E003 8>inspecteur ?");
                R(ref s, "...Blimey...", "...Miséricorde...");
                return s;
            };

            // [87] BB\script\output\_sce04_c402_0070_eng#2
            entryTranslators[@"BB\script\output\_sce04_c402_0070_eng#2"] = (s) => {
                R(ref s, "So that night ten years ago...<E049><E003 12>when I was attacked by those\r\nthugs in the back streets...", "Ainsi donc, cette nuit-là il y a dix ans... <E049><E003 12>lorsque de vulgaires\r\nvoyous m'ont agressé dans une ruelle sordide...");
                R(ref s, "...and Genshin's ring was taken.<E049><E003 14>\r\n<E025 3>That was him, <E049><E003 8>was it?", "...et que la bague de Genshin m'a été volée.<E049><E003 14>\r\n<E025 3>C'était lui, <E049><E003 8>n'est-ce pas ?");
                R(ref s, "That was Gregson <E049><E003 10><E025 2><E341>and some ‘hired help’?", "C'était l'œuvre de Gregson <E049><E003 10><E025 2><E341>et de ses « hommes de main » ?");
                R(ref s, "Then the detective handed the stolen ring to Dr Wilson...", "Puis l'inspecteur remit la bague dérobée au Dr Wilson...");
                R(ref s, "...who feigned its discovery from the victim's stomach\r\nduring that autopsy.", "...qui simula sa découverte dans l'estomac de la victime\r\nlors de l'autopsie.");
                R(ref s, "And in the light of that ‘decisive’ evidence, <E049><E003 10>Mr Asogi was\r\nfound guilty of the charges brought against him.", "Et sur la foi de cette preuve « irréfutable », <E049><E003 10>M. Asogi fut\r\ndeclaré coupable des chefs portés contre lui.");
                R(ref s, "However, <E049><E003 8>behind the scenes...", "Toutefois, <E049><E003 8>en coulisses...");
                R(ref s, "...he had actually already struck <E006>a deal<E005> with his\r\naccusers...", "...il avait en vérité déjà conclu <E006>un accord<E005> avec ses\r\naccusateurs...");
                R(ref s, "...in which he agreed to silently accept the charges.", "...par lequel il s'engageait à accepter la sentence sans un mot.");
                R(ref s, "But I just don't believe that part.", "Mais cette partie de l'histoire, je n'y crois pas.");
                R(ref s, "As far as I knew the man, <E049><E003 8>my father despised such\r\nunderhand dealings.", "Pour autant que je l'aie connu, <E049><E003 8>mon père méprisait de telles\r\nmachinations hypocrites.");
                R(ref s, "...It was extremely easy to make him comply.", "...Il a pourtant été d'une simplicité enfantine de le faire plier.");
                R(ref s, "You see, <E049><E003 10><E145 61 2><E003 5><E025 3><E239>he had one crippling <E006>weakness<E005>.", "Voyez-vous, <E049><E003 10><E145 61 2><E003 5><E025 3><E239>il avait une <E006>faiblesse<E005> fatale.");
                R(ref s, "W-<E049><E003 8>What weakness?", "Q-<E049><E003 8>Quelle faiblesse ?");
                R(ref s, "Isn't it obvious?<E049><E003 18><E145 61 7><E149 61 0 6><E003 4>\r\n<E025 3><E238>You...<E049><E003 16>Kazuma Asogi.", "N'est-ce point évident ?<E049><E003 18><E145 61 7><E149 61 0 6><E003 4>\r\n<E025 3><E238>Vous... <E049><E003 16>Kazuma Asogi.");
                R(ref s, "M-<E003 12><E025 2><E338><E342>Me?!", "M-<E003 12><E025 2><E338><E342>Moi ?!");
                R(ref s, "...Perhaps you have no desire to return to your homeland,<E049><E003 10>\r\n<E025 3>Asogi.", "...Peut-être n'avez-vous nul désir de revoir votre terre natale,<E049><E003 10>\r\n<E025 3>Asogi.");
                R(ref s, "Though I hear you have a fourteen-year-old son.", "On m'a pourtant dit que vous aviez un fils de quatorze ans.");
                R(ref s, "Agree to cooperate <E003 8>and accept your guilt without\r\ncontention...", "Acceptez de coopérer <E003 8>et plaidez coupable sans faire\r\nd'esclandre...");
                R(ref s, "...and you will see Japan –<E049><E003 8> and your son – again.", "...et vous reverrez le Japon –<E049><E003 8> ainsi que votre fils.");
                R(ref s, "You...<E003 16><E025 1><E339><E343>you scoundrel!", "Vous... <E003 16><E025 1><E339><E343>ignoble crapule !");
                R(ref s, "Whether you choose <E049><E003 8>wisely or not...", "Que vous choisissiez <E049><E003 8>la voie de la raison ou non...");
                R(ref s, "...it will be a closed trial, <E049><E003 8>by order of Her Majesty.", "...le procès se tiendra à huis clos, <E049><E003 8>sur ordre de Sa Majesté.");
                R(ref s, "So whatever rash claims you might make in court,<E049><E003 10> <E025 3>we'll\r\nhave no trouble in stifling them.", "Alors, quelles que soient vos vaines protestations dans le prétoire,<E049><E003 10> <E025 3>nous\r\nn'aurons aucune peine à les étouffer.");
                R(ref s, "There's only one outcome for you, <E049><E003 6>Asogi:<E049><E003 15>\r\n<E239><E025 3>the gallows.", "Il n'y a qu'une issue possible pour vous, <E049><E003 6>Asogi :<E049><E003 15>\r\n<E239><E025 3>le gibet.");
                R(ref s, "Don't forget <E003 8><E025 2>that I still have a weapon at my disposal.", "N'oubliez pas <E003 8><E025 2>que je détiens encore une arme redoutable.");
                R(ref s, "A document revealing <E006>a truth<E005> that I know <E145 14 64>you're<E171 14 5 1 4 2>\r\ndesperate to keep hidden.", "Un document révélant <E006>une vérité<E005> dont je sais que vous ferez tout<E171 14 5 1 4 2>\r\npour qu'elle reste secrète.");
                R(ref s, "Yes, <E049><E003 10><E025 2>it hadn't escaped my mind.<E049><E003 12> <E025 2>Which is the only reason\r\nI'm willing to bargain with you.", "Oui, <E049><E003 10><E025 2>cela ne m'avait point échappé.<E049><E003 12> <E025 2>C'est d'ailleurs l'unique raison\r\npour laquelle j'accepte de traiter avec vous.");
                R(ref s, "I only want to protect this country's law and order,<E049><E003 10> <E025 3>you\r\nunderstand.", "Je ne cherche qu'à préserver l'ordre et les institutions de ce pays,<E049><E003 10> <E025 3>comme\r\nvous le comprenez.");
                R(ref s, "So...<E003 10>what's it to be, <E049><E003 8><E025 3>Asogi?", "Alors... <E003 10>que décidez-vous, <E049><E003 8><E025 3>Asogi ?");
                R(ref s, "...Ka<E025 7>...<E003 2><E341>...<E003 4>...<E003 12><E025 4><E342>Kazuma...", "...Ka<E025 7>...<E003 2><E341>...<E003 4>...<E003 12><E025 4><E342>Kazuma...");
                return s;
            };

            // [88] BB\script\output\_sce04_c402_0070_eng#3
            entryTranslators[@"BB\script\output\_sce04_c402_0070_eng#3"] = (s) => {
                R(ref s, "He...<E049><E003 12><E025 3><E341>he did it for me...", "Il... <E049><E003 12><E025 3><E341>il a fait cela pour moi...");
                R(ref s, "And as I told him at the time, <E049><E003 8>my motive was simply to\r\nprotect Britain from the damage the truth would do.", "Et comme je le lui ai dit à l'époque, <E049><E003 8>mon but était simplement de\r\nprotéger la Grande-Bretagne du cataclysme qu'engendrerait la vérité.");
                R(ref s, "To protect this country's law and order...<E049><E003 15><E025 3>at any cost.", "De préserver l'ordre public de ce royaume...<E049><E003 15><E025 3>à tout prix.");
                R(ref s, "I've never dared let myself even consider this possibility\r\nuntil now...", "Je n'avais jamais osé envisager une telle éventualité jusqu'à\r\nce jour...");
                R(ref s, "...but in the light of all this...<E003 12><E025 3>treachery, <E049><E003 12>I have to ask:", "...mais à la lumière de toute cette... <E003 12><E025 3>trahison, <E049><E003 12>je dois poser la question :");
                R(ref s, "<E006>The mastermind<E005> behind the Reaper of the Bailey...", "<E006>L'instigateur<E005> dissimulé derrière le Faucheur de la Cour...");
                R(ref s, "Was it you...<E049><E003 20><E338><E341><E025 3>Lord Mael Stronghart?", "Était-ce vous... <E049><E003 20><E338><E341><E025 3>Lord Mael Stronghart ?");
                R(ref s, "A rather brilliant idea, <E049><E003 6>wouldn't you say...<E049><E003 14>\r\n<E025 3>Lord Barok van Zieks?", "Une idée proprement magistrale, <E049><E003 6>ne trouvez-vous point...<E049><E003 14>\r\n<E025 3>Lord Drake Van Peers ?");
                R(ref s, "That the spirit of your late brother –<E049><E003 8><E025 3> that paragon of\r\njustice –<E049><E003 10> <E025 2>should return to reap justice for his sibling.", "Que l'âme vengeresse de votre défunt frère –<E049><E003 8><E025 3> ce parangon de\r\njustice –<E049><E003 10> <E025 2>revienne faucher les coupables au nom de son cadet.");
                R(ref s, "Could there be a more appetising tale for London's\r\nmasses, <E049><E003 6><E025 3>I ask you?", "Pouvait-on rêver conte plus séduisant pour le petit peuple de Londres,<E049><E003 6><E025 3> je vous le demande ?");
                R(ref s, "What...<E049><E003 12>what brazen...", "Quel... <E049><E003 12>quel cynisme éhonté...");
                R(ref s, "I knew that you'd play the part to perfection.", "Je savais que vous tiendriez votre rôle à la perfection.");
                R(ref s, "But your role really wasn't that of some embodiment of\r\nDeath.<E049><E003 8> <E145 61 10><E118 61 1.2><E003 20><E025 3>No, <E049><E003 10><E025 2>you were London's guardian angel.", "Mais votre fonction n'était pas celle d'une sombre incarnation de\r\nla Mort.<E049><E003 8> <E145 61 10><E118 61 1.2><E003 20><E025 3>Non, <E049><E003 10><E025 2>vous étiez l'ange gardien de Londres.");
                R(ref s, "An angel with bloody hands?<E049><E003 14> I think not.", "Un ange aux mains rougies de sang ?<E049><E003 14> Laissez-moi rire.");
                R(ref s, "Those who had cooperated with me already were only\r\ntoo happy to participate in my plan.", "Ceux qui avaient déjà conspiré avec moi n'étaient que trop heureux\r\nde prêter leur concours à mon dessein.");
                R(ref s, "Inspector Gregson...<E049><E003 12>Dr Wilson...", "L'inspecteur Gregson...<E049><E003 12>Le Dr Wilson...");
                R(ref s, "My minions worked tirelessly to ensure that the finger of\r\nguilt could never come to rest on you.", "Mes affidés ont œuvré sans relâche afin que le soupçon du crime\r\nne puisse jamais effleurer votre personne.");
                R(ref s, "It's all thanks to them that you were exalted <E049><E003 10><E025 3>as the\r\ndemigod the Reaper became.", "C'est entièrement grâce à eux que vous fûtes érigé <E049><E003 10><E025 3>en ce demi-dieu\r\nqu'est devenu le Faucheur.");
                R(ref s, "But Dr Wilson left Britain four years ago <E049><E003 6><E145 112 0><E118 112 1.3><E003 8><E025 3>when he was\r\ninvited to work in Japan.", "Mais le Dr Wilson a quitté l'Angleterre il y a quatre ans, <E049><E003 6><E145 112 0><E118 112 1.3><E003 8><E025 3>invité\r\nà exercer ses fonctions au Japon.");
                R(ref s, "That's right.", "En effet.");
                R(ref s, "So I had to employ the services of his young <E006>protégée<E005>\r\nafter that.", "J'ai donc dû recourir aux bons soins de sa jeune <E006>protégée<E005>\r\npar la suite.");
                R(ref s, "Dr Courtney Sithe.", "Le Dr Courtney Sithe.");
                R(ref s, "Dr Sithe...", "Le Dr Sithe...");
                R(ref s, "So what with the execution of the Professor and the\r\nsubsequent reign of the Reaper of the Bailey...", "Ainsi, de l'exécution du Professeur au règne subséquent\r\ndu Faucheur de la Cour...");
                R(ref s, "...I've successfully safeguarded law and order in our\r\nmighty capital for the past decade.", "...j'ai avec brio sauvegardé l'ordre et la sécurité de notre glorieuse\r\ncapitale tout au long de cette décennie écoulée.");
                R(ref s, "That...<E003 12><E025 3>is everything.", "Voilà... <E003 12><E025 3>toute l'histoire.");
                return s;
            };

            // [89] BB\script\output\_sce04_c403_0000_eng#2
            entryTranslators[@"BB\script\output\_sce04_c403_0000_eng#2"] = (s) => {
                R(ref s, "My lords, <E049><E003 8>ladies <E049><E003 8>and gentlemen...<E049><E003 14>I do hereby confess.<E049><E003 14>\r\n<E025 2>It was I who sired the concept of the Reaper.", "Messeigneurs, <E049><E003 8>mesdames <E049><E003 8>et messieurs...<E049><E003 14>je confesse solennellement.<E049><E003 14>\r\n<E025 2>C'est moi qui ai forgé le mythe du Faucheur.");
                R(ref s, "However...<E049><E003 12><E025 3>let me say in my defence...", "Cependant... <E049><E003 12><E025 3>laissez-moi ajouter pour ma défense...");
                R(ref s, "...it was all for the preservation of law and order across\r\nthe entire empire!", "...que tout cela ne visait que la sauvegarde de l'ordre public\r\ndans l'Empire tout entier !");
                R(ref s, "Lord Stronghart did it...?", "Lord Stronghart a fait cela... ?");
                R(ref s, "An unforgivable collection of crimes!<E003 14>\r\n<E042><CNTR><E025 3>But still...", "Une suite de crimes impardonnables !<E003 14>\r\n<E042><CNTR><E025 3>Mais quand même...");
                R(ref s, "All those who died at the Reaper's hand\r\n<E042><CNTR>were rotten to the core anyway...", "Tous ceux qui ont péri sous la faux du Faucheur\r\n<E042><CNTR>étaient corrompus jusqu'à la moelle de toute façon...");
                R(ref s, "If it was all in aid of keeping London safe...", "Si ce n'était que pour assurer la sécurité de Londres...");
                R(ref s, "There is no one left now who can reveal the precise truth\r\nof what happened ten years ago.", "Il ne reste désormais plus personne capable d'établir la vérité absolue\r\nsur les événements survenus il y a dix ans.");
                R(ref s, "Therefore, <E049><E003 10><E025 2>this trial can go no further.", "Dès lors, <E049><E003 10><E025 2>ce procès ne saurait se poursuivre davantage.");
                R(ref s, "Now, <E049><E003 10><E025 2>I would like to entreat all those present...", "À présent, <E049><E003 10><E025 2>j'en appelle à toutes les personnes ici réunies...");
                R(ref s, "Beyond these four walls, <E049><E003 8>nobody need know the truth.<E049><E003 12>\r\n<E025 2>Even Her Majesty must be protected from this.", "Au-delà de cette enceinte, <E049><E003 8>nul n'a besoin de connaître la vérité.<E049><E003 12>\r\n<E025 2>Sa Majesté elle-même se doit d'être préservée de cette révélation.");
                R(ref s, "I trust you all appreciate the importance of my request.<E049><E003 8><E145 61 4><E118 61 0.55><E003 20>\r\n<E025 3>It is of course <E049><E003 10>for the good of the country.", "J'ai la certitude que vous mesurez tous la portée de ma demande.<E049><E003 8><E145 61 4><E118 61 0.55><E003 20>\r\n<E025 3>Il y va naturellement <E049><E003 10>de l'intérêt supérieur de la nation.");
                R(ref s, "(Can, <E003 8>can he do this?)", "(A... <E003 8>a-t-il vraiment le droit de faire ça ?)");
                R(ref s, "(Can the trial really end now?)", "(Le procès peut-il réellement s'achever ainsi ?)");
                R(ref s, "I have one last question...", "J'ai une dernière question...");
                R(ref s, "...for the accused, <E049><E003 10><E025 3>Lord van Zieks.", "...pour l'accusé, <E049><E003 10><E025 3>Lord Van Peers.");
                R(ref s, "Of course, <E049><E003 8>I know that you're a highly accomplished\r\nprosecutor.", "Certes, <E049><E003 8>je n'ignore rien de vos exceptionnels talents de\r\nprocureur.");
                R(ref s, "So I find it hard to believe...<E049><E003 12>that you didn't have any\r\n<E006>doubts<E005> at all.", "Aussi m'est-il difficile de croire... <E049><E003 12>que vous n'ayez jamais nourri\r\nle moindre <E006>doute<E005>.");
                R(ref s, "That you never suspected your older brother.", "Que vous n'ayez jamais suspecté votre propre frère.");
                R(ref s, "Yes, <E049><E003 10><E145 1 85><E118 1 1.1><E003 8><E025 2>the same thought occurred to me.", "Oui, <E049><E003 10><E145 1 85><E118 1 1.1><E003 8><E025 2>la même interrogation m'a traversé l'esprit.");
                R(ref s, "It was only once, <E049><E003 12>but...<E003 14><E025 4>yes.<E049><E003 16> <E239><E025 3>I couldn't say that I never had\r\nmy doubts.", "Ce ne fut qu'une seule fois, mais... <E003 14><E025 4>oui.<E049><E003 16> <E239><E025 3>Je ne saurais prétendre n'avoir jamais\r\néprouvé de doutes.");
                R(ref s, "My brother's sense of justice was extremely strong.<E049><E003 12>\r\n<E025 3>Perhaps...<E003 12>too strong, <E049><E003 8>I observed.", "Le sens de la justice de mon frère était d'une rigueur absolue.<E049><E003 12>\r\n<E025 3>Peut-être... <E003 12>trop intransigeant, <E049><E003 8>avais-je remarqué.");
                R(ref s, "At that time, <E049><E003 10><E025 2>there were members of the aristocracy who\r\nwere bleeding the country dry for their own gain.", "À cette époque, <E049><E003 10><E025 2>certains membres de l'aristocratie\r\nsaignaient notre patrie à blanc pour leur propre enrichissement.");
                R(ref s, "And since they were nobles, <E049><E003 8><E025 3>they were untouchable.<E049><E003 10>\r\n<E025 3>For my brother, <E049><E003 8>it was a source of great turmoil.", "Et protégés par leur rang, <E049><E003 8><E025 3>ils demeuraient intouchables.<E049><E003 10>\r\n<E025 3>Pour mon frère, <E049><E003 8>c'était un tourment intolérable.");
                R(ref s, "And coincidentally at the same time, <E049><E003 10><E145 61 7><E118 61 0.7><E025 3>the Professor began\r\nhis terrifying reign.", "Et comme par un fait exprès, à la même période, <E049><E003 10><E145 61 7><E118 61 0.7><E025 3>le Professeur entama\r\nson règne de terreur.");
                R(ref s, "During the time of the Professor killings, <E049><E003 8><E145 18 0><E118 18 1.2><E003 10><E025 3>my brother did\r\nnot appear to be himself.", "Tout au long de cette série de meurtres, <E049><E003 8><E145 18 0><E118 18 1.2><E003 10><E025 3>mon frère n'avait plus\r\nl'air d'être lui-même.");
                R(ref s, "And <E145 1 0><E118 1 1.2><E149 1 0 8>that made you suspect?", "Et <E145 1 0><E118 1 1.2><E149 1 0 8>c'est cela qui a éveillé vos soupçons ?");
                R(ref s, "But it was <E006>only once<E005>.<E049><E003 12>\r\nNot more.", "Mais ce ne fut <E006>qu'une seule fois<E005>.<E049><E003 12>\r\nJamais plus.");
                R(ref s, "Only once?<E049><E003 10> Really?", "Une seule fois ?<E049><E003 10> Vraiment ?");
                R(ref s, "Klint wasn't the culprit.<E049><E003 10><E145 18 0><E118 18 0.85><E003 12>\r\n<E025 2>That was my conclusion at the time.", "Klint n'était pas le coupable.<E049><E003 10><E145 18 0><E118 18 0.85><E003 12>\r\n<E025 2>Telle fut ma conclusion à l'époque.");
                return s;
            };

            // [90] BB\script\output\_sce04_c403_0000_eng#3
            entryTranslators[@"BB\script\output\_sce04_c403_0000_eng#3"] = (s) => {
                R(ref s, "Klint wasn't the culprit.<E049><E003 10><E145 18 0><E118 18 0.85><E003 12>\r\n<E025 2>That was my conclusion at the time.", "Klint n'était pas le coupable.<E049><E003 10><E145 18 0><E118 18 0.85><E003 12>\r\n<E025 2>Telle fut ma conclusion à l'époque.");
