            };

            // [91] BB\script\output\_sce04_c403_0000_eng#4
            entryTranslators[@"BB\script\output\_sce04_c403_0000_eng#4"] = (s) => {
                R(ref s, "And I still believe that now.", "Et j'en demeure convaincu aujourd'hui encore.");
                R(ref s, "Do you have any evidence to support that idea?", "Avez-vous le moindre élément pour étayer cette certitude ?");
                R(ref s, "The third victim...<E003 14><E025 2>was the Lord Chief Justice at the time.", "La troisième victime... <E003 14><E025 2>n'était autre que le Lord juge en chef d'alors.");
                R(ref s, "It was he who had recognised my brother's potential and\r\ntrained him as a prosecutor.", "C'était lui qui avait discerné le talent de mon frère et l'avait\r\nformé au métier de procureur.");
                R(ref s, "No matter what the circumstances, <E049><E003 12><E025 1><E346><E339><E342>it's unthinkable that\r\nmy brother could have killed his friend and mentor!", "Quelles qu'eussent été les circonstances, <E049><E003 12><E025 1><E346><E339><E342>il est impensable que\r\nmon frère ait pu ôter la vie à son ami et mentor !");
                return s;
            };

            // [92] BB\script\output\_sce04_c403_0000_eng#5
            entryTranslators[@"BB\script\output\_sce04_c403_0000_eng#5"] = (s) => {
